service = {
    "image": "postgres:16",
    "environment": {"POSTGRES_DB": "warehouse", "POSTGRES_PASSWORD": "change-me"},
    "ports": ["5433:5432"],
    "volumes": ["pgdata:/var/lib/postgresql/data"],
}


def build_run(name, service):
    parts = ["docker", "run", "--name", name]
    for key in sorted(service.get("environment", {})):
        parts += ["-e", f"{key}={service['environment'][key]}"]
    for port in service.get("ports", []):
        parts += ["-p", port]
    for volume in service.get("volumes", []):
        parts += ["-v", volume]
    parts += ["-d", service["image"]]
    return " ".join(parts)


